    let mut periods: Vec<(u8, u64)> = Vec::new();
    for u in 0..(DIALECT_COUNT as u8) {
        let seq: Vec<u8> = tuples.iter().map(|ig| dialect_all_pass(u, ig) as u8).collect();
        let p = min_period(&seq) as u64;
        periods.push((u, p));
        if let Some(r) = true_order {
            if p == r { hits.push(u); }
        }
    }
    match true_order {
        Some(r) => out.push_str(&format!("dialects whose gate-pass period equals the true order {}: {:?} (of {} checked)\n", r, hits, DIALECT_COUNT)),
        None => {}
    }

    // DECOMPOSITION READOUT: every dialect's own gate-pass period, grouped by
    // value, with whether each divides the true order. If the order factors as
    // a join (LCM) of short per-dialect periods, the divisors show up here as
    // cheap periods that no dialect had to walk the full order to reach — the
    // Pohlig-Hellman shape rendered as a dialect consensus, testable directly.
    let mut by_period: std::collections::BTreeMap<u64, Vec<u8>> = std::collections::BTreeMap::new();
    for &(u, p) in &periods {
        by_period.entry(p).or_default().push(u);
    }
    out.push_str(&format!("per-dialect gate-pass periods ({} distinct):\n", by_period.len()));
    for (p, us) in &by_period {
        let divides = match true_order {
            Some(r) => if r % p == 0 { if *p == r { "= order".to_string() } else { format!("| order (order/{} = {})", p, r / p) } } else { "does NOT divide order".to_string() },
            None => "order unknown".to_string(),
        };
        out.push_str(&format!("  period {:>6}  x{:>2} dialect(s) {:?}  {}\n", p, us.len(), us, divides));
    }
    if let Some(r) = true_order {
        // The lemma's live question: is the order the LCM of the proper-divisor
        // periods alone? If yes, the full-order dialects are redundant — the
        // order is reachable by combining short periods, never walking to r.
        let proper: Vec<u64> = by_period.keys().cloned().filter(|&p| p > 1 && p < r && r % p == 0).collect();
        let lcm_proper = proper.iter().fold(1u64, |acc, &p| {
            let g = { let (mut x, mut y) = (acc, p); while y != 0 { let t = x % y; x = y; y = t; } x };
            acc / g * p
        });
        out.push_str(&format!("LCM of proper-divisor periods {:?} = {}  (true order = {}, reconstructed-without-walking: {})\n",
            proper, lcm_proper, r, lcm_proper == r));
    }
    out
}

