"factor" => {
    // No size cap: numbers of any width factor here. A trailing
    // `dceil:<v>` sets the divisor ceiling for the multi-limb path
    // (default 2^24); numbers all below 2^64 take the fixed-width
    // path, which reaches the full square root.
    let mut toks: Vec<String> = parts.collect::<Vec<&str>>().join(" ")
        .split_whitespace().map(|s| s.to_string()).collect();
    let mut dceil: u64 = 1 << 24;
    if let Some(last) = toks.last() {
        if let Some(v) = last.strip_prefix("dceil:") {
            match v.parse::<u64>() { Ok(c) if c >= 3 => { dceil = c; toks.pop(); }, _ => {} }
        }
    }
    if toks.is_empty() { sprintln!("gpu_kernel factor <n> [n ...] [dceil:<v>]  -- any width; dceil bounds the divisor sweep for n >= 2^64"); }
    else {
        let mut bigs: Vec<num_bigint::BigUint> = Vec::new();
        let mut bad: Option<String> = None;
        for s in &toks {
            match s.parse::<num_bigint::BigUint>() { Ok(v) => bigs.push(v), Err(_) => { bad = Some(s.clone()); break; } }
        }
        match bad {
            Some(s) => sprintln!("gpu_kernel factor: '{}' is not a non-negative integer", s),
            None => {
                let all_u64 = bigs.iter().all(|b| b.to_u64_digits().len() <= 1);
                if all_u64 {
                    let nums: Vec<u64> = bigs.iter().map(|b| b.to_u64_digits().first().copied().unwrap_or(0)).collect();
                    sprintln!("{}", crate::gpu_kernel::bench_factor(&nums, 0));
                } else {
                    sprintln!("{}", crate::gpu_kernel::bench_factor_big(&bigs, dceil, 0));
                }
            }
        }
    }
}

