    // d stays below 2^32 (the host clamps dceil), so folding each 64-bit limb
    // as two 32-bit chunks keeps every intermediate ((r<<32)+chunk) under 2^64
    // with no 128-bit type — NVRTC gates __int128 behind a build flag, so the
    // portable path avoids it.
    unsigned long long d = 3ULL + 2ULL * (unsigned long long)t;
    unsigned long long step = 2ULL * (unsigned long long)tpn;
    for (; d <= dceil; d += step) {
        unsigned long long r = 0ULL;
        for (int i = (int)n_limbs - 1; i >= 0; i--) {
            unsigned long long limb = N[i];
            r = ((r << 32) + (limb >> 32)) % d;
            r = ((r << 32) + (limb & 0xffffffffULL)) % d;
        }
        if (r == 0ULL) { atomicMin(&out[lane], d); break; }
