    let d_limbs = match stream.clone_htod(&limbs) { Ok(d) => d, Err(e) => return format!("factor: htod: {e}") };
    let mut d_out = match stream.clone_htod(&vec![u64::MAX; k as usize]) { Ok(d) => d, Err(e) => return format!("factor: htod out: {e}") };
    let total = (k as u64) * (tpn as u64);
    let block: u32 = 256;
    let grid = ((total + block as u64 - 1) / block as u64) as u32;
    let cfg = LaunchConfig { grid_dim: (grid,1,1), block_dim: (block,1,1), shared_mem_bytes: 0 };

    // N's own bound on itself: the largest lane's sqrt, capped only by the u64
    // mulmod width. The window walks [dstart, dend) up to this bound.
    let width_cap: u64 = 1u64 << 62;
    let bound_big = nums.iter().map(big_isqrt).max().unwrap();
    let self_bound: u64 = bound_big.to_u64_digits().first().copied()
        .filter(|_| bound_big.to_u64_digits().len() <= 1)
        .map(|v| v.min(width_cap)).unwrap_or(width_cap);
    let width_bit = self_bound > width_cap - 1 && bound_big > num_bigint::BigUint::from(width_cap);

    let per_thread: u64 = 4096;
    let window: u64 = (tpn as u64) * 2 * per_thread;
    let mut dstart: u64 = 3;
    let mut launches: u64 = 0;
    let t0 = std::time::Instant::now();
    loop {
        if dstart > self_bound { break; }
        // stop if every lane already has a factor
        if let Ok(cur) = stream.clone_dtoh(&d_out) {
            if cur.iter().all(|&f| f != u64::MAX) { break; }
        }
        let dend = dstart.saturating_add(window).min(self_bound.saturating_add(1));
        { let mut b = stream.launch_builder(&func);
          b.arg(&d_limbs); b.arg(&n_limbs); b.arg(&mut d_out); b.arg(&k); b.arg(&tpn); b.arg(&dstart); b.arg(&dend);
          if let Err(e) = unsafe { b.launch(cfg) } { return format!("factor: launch: {e}"); } }
        if let Err(e) = stream.synchronize() { return format!("factor: sync: {e}"); }
        launches += 1;
        if dend > self_bound { break; }
        dstart = dend;
    }
    let res = match stream.clone_dtoh(&d_out) { Ok(v) => v, Err(e) => return format!("factor: sync: {e}") };
    let secs = t0.elapsed().as_secs_f64().max(1e-9);

    let mut out = format!("factor (multi-limb, {} limb(s), self-bound sqrt(N)={}{}): {} number(s), {} threads x {} launch(es), {:.4}s",
        n_limbs, bound_big,
        if width_bit { " capped at 2^62 by u64 mulmod width".to_string() } else { String::new() },
        k, tpn, launches, secs);
    for (i, n) in nums.iter().enumerate() {
        let f = res[i];
        if f == u64::MAX || f < 2 {
            let swept_full = !width_bit || big_isqrt(n) <= num_bigint::BigUint::from(self_bound);
            if swept_full {
                out.push_str(&format!("\n  {} : PRIME (swept to its own sqrt, no factor)", n));
            } else {
                out.push_str(&format!("\n  {} : no factor below 2^62 (sqrt beyond the u64 mulmod width)", n));
            }
        } else {
            let bf = num_bigint::BigUint::from(f);
            let (cof, rem) = (n / &bf, n % &bf);
            let ok = if rem.is_zero() { "verified" } else { "MISMATCH" };
            out.push_str(&format!("\n  {} = {} x {}  ({})", n, f, cof, ok));
        }
    }
    out
}

