/// one exit. Every fallible step lives in `factor_big_inner`, so no error path
/// leaves this function early. vox lifts a lone FSPLIT/FFUSE pair here — a fork
/// that closes, verdict T — instead of the many open forks a run of early
/// returns carries. The self-reference (a routine that bounds itself by its own
/// sqrt) is held closed, not left dangling.
#[inline(never)]
pub fn bench_factor_big(nums: &[num_bigint::BigUint], device: usize) -> String {
    let text;
    match factor_big_inner(nums, device) {
        Ok(s) => { text = s; }
        Err(s) => { text = s; }
    }
    text
}

