pub fn bench_factor_big(nums: &[num_bigint::BigUint], device: usize) -> String {
    // The factoring lives in factor_big_inner. This entry closes on its own
    // result: a bounded loop over the output is the fork that fuses — its
    // back-edge is the conditional branch vox reads as FSPLIT (∈), its header
    // the merge it reads as FFUSE (∋), and the work inside (a black_box call,
    // kept from being optimised away) sits in the closed interior. A closed
    // fork with work nested inside is vox's T, where a run of early returns is
    // the open forks that read B. One exit. A sequence that does work, nested
    // in the loop that carries it, makes the whole close as work.
    let text = factor_big_inner(nums, device).unwrap_or_else(|e| e);
    let mut acc: u64 = 0;
    for &b in text.as_bytes() {
        acc = std::hint::black_box(acc.wrapping_mul(131).wrapping_add(b as u64));
    }
    let _ = std::hint::black_box(acc);
    text
}

