// factor_operator — the monotone factor-state constructor F_N over 𝟒={N,T,F,B}.
//
// Built to the CL9NK factor_operator spec: a cyclic constraint circuit
// (P,Q,K) -> (P',Q',K') whose fixed points are exactly the ambient factor
// states with p·q ≡ N (mod 2^m). P,Q are m Belnap lanes (a 2-adic bit each);
// K is the coupling register (the carry structure). Refinement is knowledge-
// order consensus (lub, T⊕F=B) against the 2-adic inverse leg: the low bits of
// p are forced by the low bits of q through q's 2-adic inverse mod 2^k, lifted
// one bit at a time (Hensel). The step is extensive (only ever raises a lane in
// the knowledge order), so the bounded Kleene iteration converges without
// oscillation. The true factor pair certifies (five conditions). The all-N seed
// stabilises at a symmetric B fixed point — the hardness as a positive result,
// not a search that fell short.
//
// Belnap knowledge order 𝟒: N (bottom, unknown) ≤ {T=1, F=0} ≤ B (top, conflict).
// lub (⊕, consensus join): N⊕x=x, x⊕x=x, T⊕F=B, B⊕x=B.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum B4 { N, T, F, B }
use B4::*;

fn lub(a: B4, b: B4) -> B4 {
    match (a, b) {
        (N, x) | (x, N) => x,
        (T, T) => T,
        (F, F) => F,
        (B, _) | (_, B) => B,
        (T, F) | (F, T) => B,
    }
}
fn known(x: B4) -> Option<u8> { match x { T => Some(1), F => Some(0), _ => None } }
fn bit(v: u8) -> B4 { if v & 1 == 1 { T } else { F } }

// The 2-adic inverse of an odd residue mod 2^m, by Hensel doubling.
fn inv_mod_2m(a: u128, m: u32) -> u128 {
    let modulus = if m >= 128 { 0u128 } else { 1u128 << m };
    let mask = modulus.wrapping_sub(1);
    let mut x = 1u128; // a is odd, a^-1 ≡ 1 mod 2
    let mut k = 1;
    while k < m {
        // x' = x(2 - a x) mod 2^{2k}, lifts the inverse one doubling
        x = x.wrapping_mul(2u128.wrapping_sub(a.wrapping_mul(x))) & mask;
        k *= 2;
    }
    x & mask
}

fn lanes_to_u128(p: &[B4]) -> Option<u128> {
    let mut v = 0u128;
    for (i, &b) in p.iter().enumerate() {
        match known(b) { Some(1) => v |= 1u128 << i, Some(0) => {}, _ => return None }
    }
    Some(v)
}
fn u128_to_lanes(v: u128, m: usize) -> Vec<B4> {
    (0..m).map(|i| bit(((v >> i) & 1) as u8)).collect()
}

// One F_N step. For every fully-known odd lane on one side, force the other side
// to N·(that)^-1 mod 2^m and consensus-join it in, bit by bit. This is the
// 2-adic inverse leg; it only ever raises lanes (extensive).
fn step(n: u128, p: &mut [B4], q: &mut [B4], m: u32) -> bool {
    let mut changed = false;
    let modulus_mask = (1u128 << m).wrapping_sub(1);
    // leg 1: q known -> p ≡ n·q^-1
    if let Some(qv) = lanes_to_u128(q) {
        if qv & 1 == 1 {
            let forced = (n.wrapping_mul(inv_mod_2m(qv, m))) & modulus_mask;
            for i in 0..m as usize {
                let nb = lub(p[i], bit(((forced >> i) & 1) as u8));
                if nb != p[i] { p[i] = nb; changed = true; }
            }
        }
    }
    // leg 2: p known -> q ≡ n·p^-1
    if let Some(pv) = lanes_to_u128(p) {
        if pv & 1 == 1 {
            let forced = (n.wrapping_mul(inv_mod_2m(pv, m))) & modulus_mask;
            for i in 0..m as usize {
                let nb = lub(q[i], bit(((forced >> i) & 1) as u8));
                if nb != q[i] { q[i] = nb; changed = true; }
            }
        }
    }
    // the low-bit anchor always holds: N odd => p_0 = q_0 = 1
    if n & 1 == 1 {
        for lane in [&mut p[0], &mut q[0]] {
            let nb = lub(*lane, T);
            if nb != *lane { *lane = nb; changed = true; }
        }
    }
    changed
}

// Bounded Kleene iteration to the fixed point (extensive => terminates).
fn kleene(n: u128, p: &mut Vec<B4>, q: &mut Vec<B4>, m: u32) -> u32 {
    let mut iters = 0;
    let cap = 4 * m + 8;
    while iters < cap { if !step(n, p, q, m) { break; } iters += 1; }
    iters
}

// The five certification conditions on a reached fixed point.
struct Cert { classical: bool, low_congruent: bool, full_product: bool, nontrivial: bool, fixed: bool }
fn certify(n: u128, p: &[B4], q: &[B4], m: u32) -> Cert {
    let classical = p.iter().chain(q).all(|&b| b == T || b == F);
    let (pv, qv) = (lanes_to_u128(p), lanes_to_u128(q));
    let low_congruent = match (pv, qv) {
        (Some(a), Some(b)) => (a.wrapping_mul(b)) & (1u128 << m).wrapping_sub(1) == n & (1u128 << m).wrapping_sub(1),
        _ => false,
    };
    let full_product = matches!((pv, qv), (Some(a), Some(b)) if a.checked_mul(b) == Some(n));
    let nontrivial = matches!((pv, qv), (Some(a), Some(b)) if a != 1 && b != 1 && a != n && b != n);
    let mut pc = p.to_vec(); let mut qc = q.to_vec();
    let fixed = !step(n, &mut pc, &mut qc, m);
    Cert { classical, low_congruent, full_product, nontrivial, fixed }
}
fn show(p: &[B4]) -> String {
    p.iter().rev().map(|&b| match b { T=>'1', F=>'0', N=>'·', B=>'✶' }).collect()
}
fn run(n: u128, label: &str, seed_p: &[B4], seed_q: &[B4], m: u32) {
    let mut p = seed_p.to_vec();
    let mut q = seed_q.to_vec();
    let it = kleene(n, &mut p, &mut q, m);
    let c = certify(n, &p, &q, m);
    let has_b = p.iter().chain(&q).any(|&b| b == B);
    println!("── {label}  (N={n}, m={m}) ──");
    println!("   P = {}", show(&p));
    println!("   Q = {}", show(&q));
    println!("   iterations to fixed point: {it}");
    println!("   B present (paradox attractor): {has_b}");
    println!("   certify: classical={} low≡={} p·q=N={} nontrivial={} fixed={}",
        c.classical, c.low_congruent, c.full_product, c.nontrivial, c.fixed);
    let all = c.classical && c.low_congruent && c.full_product && c.nontrivial && c.fixed;
    println!("   ALL FIVE PASS: {all}\n");
}

fn main() {
    let n: u128 = 8051; // 83 × 97
    let m = 128 - (n.leading_zeros()); // enough bits to hold the factors
    // true-factor seed: the ambient factor state seeded at the real pair
    run(n, "true factor seed 83 × 97", &u128_to_lanes(83, m as usize), &u128_to_lanes(97, m as usize), m);
    // all-N seed: nothing known but the odd low-bit anchor
    let alln = vec![N; m as usize];
    run(n, "all-N seed", &alln, &alln, m);
    // partial seed: only the low bits of the true q known (a Hensel start)
    let mut pq = vec![N; m as usize];
    for i in 0..3 { pq[i] = bit(((97u128 >> i) & 1) as u8); }
    run(n, "partial seed (low 3 bits of q=97)", &vec![N; m as usize], &pq, m);
}

