// One F_N step, by the per-column 2-adic congruence (the inverse leg, resolved
// one bit at a time so partial seeds Hensel-force across). It only ever raises
// lanes in the knowledge order, so it is extensive.
//
// With p_0 = q_0 = 1, bit k of p·q is C_k + p_k + q_k (mod 2), where C_k is bit
// k of the product of the already-fixed low parts. The congruence p·q ≡ N then
// gives p_k + q_k ≡ r_k := N_k ⊕ C_k. Given a classical low run below k:
//   one side known  -> the other is forced classical (r_k ⊕ it),
//   both unknown    -> both completions hold, the join is T⊕F = B (the paradox),
//   both known      -> a consistency check (a real factor seed passes).
// Above the first B the low run is broken, so the remaining free lanes take B
// by the symmetric consensus: unresolved coupling stabilises at B, not unknown.
fn step(n: u128, p: &mut [B4], q: &mut [B4], m: u32) -> bool {
    let mut changed = false;
    // low-bit anchor: N odd => p_0 = q_0 = 1
    if n & 1 == 1 {
        for lane in [&mut p[0], &mut q[0]] {
            let nb = lub(*lane, T);
            if nb != *lane { *lane = nb; changed = true; }
        }
    }
    for k in 1..m as usize {
        // need the whole low run below k classical to know C_k
        let low_classical = (0..k).all(|i| known(p[i]).is_some() && known(q[i]).is_some());
        if !low_classical { break; }
        let plow: u128 = (0..k).map(|i| (known(p[i]).unwrap() as u128) << i).sum();
        let qlow: u128 = (0..k).map(|i| (known(q[i]).unwrap() as u128) << i).sum();
        let c_k = ((plow.wrapping_mul(qlow)) >> k) & 1;
        let n_k = (n >> k) & 1;
        let r_k = (n_k ^ c_k) as u8; // p_k ⊕ q_k = r_k
        match (known(p[k]), known(q[k])) {
            (Some(pk), None) => { let f = bit(r_k ^ pk); if q[k] != f { q[k] = f; changed = true; } }
            (None, Some(qk)) => { let f = bit(r_k ^ qk); if p[k] != f { p[k] = f; changed = true; } }
            (None, None) => { p[k] = B; q[k] = B; changed = true; break; }
            (Some(_), Some(_)) => { /* both fixed: consistency already carried */ }
        }
    }
    // symmetric consensus above the break: any still-free lane joins to B
    for i in 1..m as usize {
        if p[i] == N { p[i] = B; changed = true; }
        if q[i] == N { q[i] = B; changed = true; }
    }
    changed
}

