//! K the coupling register (the carry). Refinement is knowledge-order consensus
//! against the 2-adic inverse leg, resolved one bit at a time so a partial seed
//! Hensel-lifts across. The step only ever raises a lane in the knowledge order,
//! so the bounded Kleene iteration converges without oscillation.
//!
//! The true factor pair is a certified fixed point (five conditions pass). The
//! all-N seed converges to the symmetric paradox fixed point: bit 0 is the odd
//! anchor, every free bit above it is B. That B-attractor is the hardness as a
//! positive result, and the count of B lanes is the moat width — the number of
//! factor bits the 2-adic structure leaves undetermined.
//!
//! Belnap knowledge order: N (unknown, bottom) ≤ {T=1, F=0} ≤ B (conflict, top).
//! Consensus join (lub): N⊕x=x, x⊕x=x, T⊕F=B, B⊕x=B.

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum B4 { N, T, F, B }
use B4::*;

fn lub(a: B4, b: B4) -> B4 {
    match (a, b) {
        (N, x) | (x, N) => x,
        (T, T) => T,
        (F, F) => F,
        _ => B,
    }
}
fn known(x: B4) -> Option<u8> { match x { T => Some(1), F => Some(0), _ => None } }
fn bit(v: u8) -> B4 { if v & 1 == 1 { T } else { F } }

fn u128_to_lanes(v: u128, m: usize) -> Vec<B4> {
    (0..m).map(|i| bit(((v >> i) & 1) as u8)).collect()
}
fn lanes_to_u128(p: &[B4]) -> Option<u128> {
    let mut v = 0u128;
    for (i, &b) in p.iter().enumerate() {
        match known(b) { Some(1) => v |= 1u128 << i, Some(0) => {}, _ => return None }
    }
    Some(v)
}

/// One F_N step by the per-column 2-adic congruence. With p_0=q_0=1, bit k of
/// p·q is C_k + p_k + q_k (mod 2), C_k the bit-k of the fixed low parts' product;
/// the congruence gives p_k ⊕ q_k = r_k := N_k ⊕ C_k. On a classical low run:
/// one side known forces the other, both unknown joins to B (the paradox), both
/// known is the consistency the true factor passes. Above the first B the run
/// breaks, so the remaining free lanes take B by symmetric consensus.
pub fn step(n: u128, p: &mut [B4], q: &mut [B4], m: u32) -> bool {
    let mut changed = false;
    if n & 1 == 1 {
        for lane in [&mut p[0], &mut q[0]] {
            let nb = lub(*lane, T);
            if nb != *lane { *lane = nb; changed = true; }
        }
    }
    for k in 1..m as usize {
        let low_classical = (0..k).all(|i| known(p[i]).is_some() && known(q[i]).is_some());
