pub struct FixRun {
    pub state: FactorState,
    pub iterations: usize,
    pub converged: bool,
}

pub fn fixed_point(n: &BigUint, m: usize, s0: &FactorState, max_iters: usize) -> FixRun {
    let mut s = s0.clone();
    for i in 0..max_iters {
        let s2 = fn_step(n, m, &s);
        if s2 == s {
