pub fn resolve_moat(n: u128, max_nodes: u64) -> (Option<(u128, u128)>, u64, bool) {
    // isqrt for the magnitude bound
    let mut r = n; { let mut y = (r + 1) / 2; while y < r { r = y; y = (r + n / r) / 2; } }
    let root = r;
    let bits = 128 - n.leading_zeros();
    let mut nodes: u64 = 0;
    let mut found: Option<(u128, u128)> = None;
    // DFS stack of (level k, p_low, q_low)
    let mut stack: Vec<(u32, u128, u128)> = vec![(0, 0, 0)];
    while let Some((k, plo, qlo)) = stack.pop() {
        if found.is_some() || nodes >= max_nodes { break; }
        if k >= bits + 1 { continue; }
        let modk = if k + 1 >= 127 { u128::MAX } else { (1u128 << (k + 1)) - 1 };
        for pk in 0u128..2 {
            for qk in 0u128..2 {
                let p = plo | (pk << k);
                let q = qlo | (qk << k);
                nodes += 1;
                // 2-adic winding constraint at this level
                if (p.wrapping_mul(q)) & modk != n & modk { continue; }
                if p.wrapping_mul(q) == n && p > 1 && q > 1 {
                    let (a, b) = if p <= q { (p, q) } else { (q, p) };
                    found = Some((a, b));
                }
                // magnitude bound: the smaller factor cannot exceed √N; once a
                // lane's fixed low bits already pass √N it cannot be that factor.
                if p > root && q > root { continue; }
                stack.push((k + 1, p, q));
            }
        }
    }
    (found, nodes, nodes >= max_nodes)
}

