pub fn fermat_correct(n: &BigUint, max_steps: u64) -> Option<(BigUint, BigUint)> {
    let one = BigUint::one();
    let mut a = isqrt_big(n);
    if &a * &a < *n { a += &one; }
    let mut steps = 0u64;
    loop {
        let b2 = &a * &a - n;
        let b = isqrt_big(&b2);
        if &b * &b == b2 {
            let p = &a - &b;
            let q = &a + &b;
            if p > one && q > one && &p * &q == *n {
                return Some((p, q));
            }
        }
        a += &one;
        steps += 1;
        if steps >= max_steps { return None; }
    }
}

