    "A",   // k=0
    "A",   // k=1
    "A",   // k=2
    "A",   // k=3
    "A",   // k=4
    "Ftf", // k=5
    "Ftf", // k=6
    "Ftf", // k=7
    "Ftf", // k=8
    "Ttf", // k=9
    "Ttf", // k=10
