    "T",   // k=12
    "T",   // k=13
    "A",   // k=14
    "A",   // k=15
    "A",   // k=16
];

pub enum B4Verdict { T, F, B, N }

impl core::fmt::Display for B4Verdict {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            B4Verdict::T => write!(f, "T"),
            B4Verdict::F => write!(f, "F"),
