/// The doubly-nested glyph word (inner word wrapped in outer frame).
pub const WORD: &str = "⊢∈⊤∈≻⊤≺⊥⋈⊙⊞∋∋⊡⊣";
pub const PERIOD: usize = 15;
pub const PHASE_BEARING: bool = true;

/// Landing register states at each ROTAT cut k=0..16.
/// 5 distinct states: A, Ftf, Ttf, tf, T
/// (kernel-verified: period=17, 5 distinct, final=A, banked=OK, 2 live clears)
pub const LANDINGS: [&str; 17] = [
    "A",   // k=0
    "A",   // k=1
    "A",   // k=2
    "A",   // k=3
    "A",   // k=4
    "Ftf", // k=5
    "Ftf", // k=6
    "Ftf", // k=7
    "Ftf", // k=8
    "Ttf", // k=9
    "Ttf", // k=10
    "tf",  // k=11
    "T",   // k=12
    "T",   // k=13
    "A",   // k=14
    "A",   // k=15
    "A",   // k=16
];

pub enum B4Verdict { T, F, B, N }

impl core::fmt::Display for B4Verdict {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            B4Verdict::T => write!(f, "T"),
            B4Verdict::F => write!(f, "F"),
            B4Verdict::B => write!(f, "B"),
            B4Verdict::N => write!(f, "N"),
        }
    }
}

pub fn landing_at(k: usize) -> &'static str { LANDINGS[k % PERIOD] }
pub fn winding_number() -> &'static str { "0/1" }

// ── String helpers — only what verdict_for's small-N cases need ────────

fn trim(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i + 1 < bytes.len() && bytes[i] == b'0' { i += 1; }
    String::from(&s[i..])
}

fn eq(a: &str, b: &str) -> bool { trim(a) == trim(b) }

fn lt(a: &str, b: &str) -> bool {
    let ta = trim(a);
    let tb = trim(b);
    if ta.len() != tb.len() { return ta.len() < tb.len(); }
    ta < tb
}

// ── B4 verdict ────────────────────────────────────────────────────────────────

pub fn verdict_for(n_str: &str) -> B4Verdict {
    if eq(n_str, "1") { return B4Verdict::B; }
    if lt(n_str, "1") { return B4Verdict::F; }
    match is_prime(n_str) {
        PrimeVerdict::Prime => B4Verdict::T,
        PrimeVerdict::Composite => B4Verdict::F,
        PrimeVerdict::Undetermined => B4Verdict::N,
    }
}

// ── REPL entry ────────────────────────────────────────────────────────────────

pub fn repl_doubly_nested_oneshot(args: &[&str]) {
    if args.is_empty() || args[0] == "help" {
        sprintln!("doubly_nested_oneshot <N> — one level deeper than nested_oneshot");
        sprintln!("  Word: ⊢∈⊤∈≻⊤≺⊥⋈⊙⊞∋∋⊡⊣  (period 15, 5 distinct landings)");
        sprintln!("  N has ARBITRARY LENGTH (BigUint, no fixed digit limit).");
        sprintln!("  Returns B4 verdict: T (prime), F (composite), B (paradice),");
        sprintln!("  N (undetermined — order search exceeded its step budget).");
        sprintln!("  Subcommands:");
        sprintln!("    dnos word        — canonical glyph word");
        sprintln!("    dnos cycle       — ROTAT orbit with landing register");
        sprintln!("    dnos verdict N   — B4 verdict for N");
        sprintln!("    dnos winding    — winding number");
        sprintln!("    dnos landings    — landing register states by k");
        sprintln!("    dnos factor N   — factor via winding-order search (arbitrary length)");
        sprintln!("  Examples:");
        sprintln!("    dnos 17");
        sprintln!("    dnos factor 1234567");
        sprintln!("    dnos factor 99999999999999999999999999999999999999999");
        return;
    }

    let sub = args[0];
    match sub {
        "word" => {
            sprintln!("word            : {}", WORD);
            sprintln!("period          : {}", PERIOD);
            sprintln!("phase-bearing   : {}", PHASE_BEARING);
            sprintln!("nesting depth   : 2 (outer frame wraps inner)");
        }
        "cycle" => {
            sprintln!("word: {}   period {}", WORD, PERIOD);
            sprintln!("  k  landing");
            sprintln!("  ─── ───────");
            for k in 0..PERIOD { sprintln!("  {:3}  {}", k, landing_at(k)); }
            sprintln!("5 distinct landings: A, Ftf, Ttf, tf, T");
        }
        "verdict" => {
            if args.len() < 2 { sprintln!("Usage: dnos verdict <N>"); return; }
            let n = args[1];
            let v = verdict_for(n);
            let desc = match &v {
                B4Verdict::T => "one-shot closure (prime)",
                B4Verdict::F => "no closure (composite)",
                B4Verdict::B => "paradice (neither prime nor composite)",
                B4Verdict::N => "neither — winding-order search did not close within budget",
            };
            sprintln!("doubly_nested_oneshot verdict {}: {}", n, v);
            sprintln!("  └─ {}", desc);
        }
        "winding" => { sprintln!("winding: {}", winding_number()); }
        "landings" => {
            sprintln!("landing register by ROTAT cut (k=0..16):");
            for k in 0..PERIOD { sprintln!("  k={:2}: {}", k, landing_at(k)); }
        }
        "factor" => {
            if args.len() < 2 { sprintln!("Usage: dnos factor <N>"); return; }
            let n = args[1];
            match verdict_for(n) {
                B4Verdict::B => sprintln!("doubly_nested_oneshot factor {}: B — paradice (1 is the unit)", n),
                B4Verdict::N => sprintln!(
                    "doubly_nested_oneshot factor {}: N — order search on {} did not close within budget", n, n
                ),
                B4Verdict::T => sprintln!("doubly_nested_oneshot factor {}: T — prime (no non-trivial factors)", n),
                B4Verdict::F => {
                    sprintln!("doubly_nested_oneshot factor {}: F — composite (winding-order search)", n);
                    match BigUint::from_str(n) {
                        Ok(nb) => {
                            let (depth, found) = find_optimal_depth(n, 10);
                            match found {
                                Some(p) => {
                                    let q = &nb / &p;
                                    sprintln!(
                                        "closure at nesting depth {}: {} = {} × {} (Brent cycle, Grammar-derived seed c=period_at_depth({})+n mod 256)",
                                        depth, n, p, q, depth
                                    );
                                }
                                None => {
                                    sprintln!("no closure within max nesting depth 10; falling back to prime_winding's trial-divisor walk:");
                                    sprintln!("{}", factor(n));
                                }
                            }
                        }
                        Err(_) => sprintln!("{}", factor(n)),
                    }
                }
            }
        }
        _ => {
            let n = sub;
            let v = verdict_for(n);
            let desc = match &v {
                B4Verdict::T => "prime",
                B4Verdict::F => "composite",
                B4Verdict::B => "paradice",
                B4Verdict::N => "undetermined",
            };
            sprintln!("{}", v);
            sprintln!("  └─ {}: {} (doubly-nested)", desc, n);
        }
    }
}

//! membrane_family.rs — every factorizer ob3ect word run AS a membrane.
//!
//! An ob3ect is a sequence of morphisms. Every token is a process, and what the
//! process IS depends on the register. This module holds ONE register, the math
//! register, as a token->process table over a factor carrier (the same table
//! `gpu_kernel::factor_phase_leaf` proved for the live aggregate-phase word).
//! Building "all of them as membranes" is not a bespoke algorithm per word: it
//! is mounting each ob3ect word on this one register and stepping it through the
//! nested fixed-point vessel with the value N built in. Different words drive the
//! same carrier in a different order; some close a factor pair, some do not, and
//! that difference is the reading.
//!
//! The tokens (classic discriminants): 0 VINIT reset, 1 TANCH emit, 2 AFWD
//! advance a, 3 AREV root of the gap, 4 CLINK form the pair (a-b,a+b), 5 IMSCRIB
//! gap delta=a^2-N, 6 FSPLIT, 7 FFUSE, 8 EVALT band-validate, 9 EVALF square
//! test, 10 ENGAGR, 11 IFIX fix. Arithmetic is `native_numeral` word ops on the
//! numeral's own marks; BigUint is only the host boundary in and out.
#![allow(dead_code)]
extern crate alloc;
use alloc::string::String;
use alloc::vec::Vec;
use alloc::format;
use num_bigint::BigUint;
use num_traits::{One, Zero};
use crate::native_numeral::{add_via_word, subtract_via_word, multiply_via_word};

/// The math-register factor carrier. The value N and its band are built in; the
/// live morphism state (a, gap, root, the candidate pair) rides the tokens.
struct MathCarrier<'a> {
    n:&'a BigUint, lo:&'a BigUint, hi:&'a BigUint,
    a:BigUint, delta:BigUint, b:BigUint, square:bool,
    candidate:Option<(BigUint,BigUint)>, fixed:Option<(BigUint,BigUint)>,
    emitted:Option<(BigUint,BigUint)>,
}

/// The one token->process table of the math register. Byte-identical in effect
/// to `gpu_kernel::factor_phase_leaf`; kept here so the family runner is
/// self-contained and every membrane in the census rides exactly this register.
fn math_leaf(op:u32, s:&mut MathCarrier<'_>) {
    match op {
        0 => { s.delta=BigUint::zero(); s.b=BigUint::zero(); s.square=false;
               s.candidate=None; s.fixed=None; s.emitted=None; }
        2 => s.a = add_via_word(&s.a, &BigUint::one()),
        5 => s.delta = subtract_via_word(&multiply_via_word(&s.a,&s.a), s.n)
                        .unwrap_or(BigUint::zero()),
        3 => s.b = isqrt_floor(&s.delta),
        9 => s.square = multiply_via_word(&s.b,&s.b) == s.delta,
        4 if s.square && s.candidate.is_none() => {
            s.candidate = Some((
                subtract_via_word(&s.a,&s.b).unwrap_or(BigUint::zero()),
                add_via_word(&s.a,&s.b)));
        }
        8 => if let Some((p,q))=s.candidate.take() {
                if p>=*s.lo && q<=*s.hi && multiply_via_word(&p,&q)==*s.n {
                    s.candidate=Some((p,q));
                }
             },
        11 => s.fixed = s.candidate.take(),
        1 => s.emitted = s.fixed.take(),
        _ => {}
    }
}

/// Newton floor-root, host arithmetic only for the descent bound. The membrane's
/// own gap test (op 9) reconfirms b*b via word multiply, so the root is only a
/// seed the register verifies for itself.
fn isqrt_floor(n:&BigUint)->BigUint {
    if n.is_zero() { return BigUint::zero(); }
    let mut x = BigUint::one() << ((n.bits() as usize + 1)/2);
    loop {
        let y = (&x + n/&x) >> 1;
        if y >= x { return x; }
        x = y;
    }
}

/// Parse a glyph word to its classic token discriminants, boundary marks kept.
pub fn word_ops(word:&str)->Vec<u32> {
    word.chars().filter_map(|g|
        imasm_core::classic::Token::parse(&g.to_string()).map(|t| t as u32)
    ).collect()
}

/// Run one ob3ect WORD as a membrane in the math register: mount the value N,
/// seed a at ceil(sqrt(N)), and step the whole word through the nested
/// fixed-point vessel once per frontier position until the word's own processes
/// fix and emit a pair, or the band is exhausted. Returns the pair and the
/// nested mark tick count.
pub fn run_membrane(word:&str, n:&BigUint, depth:u32, max_steps:u64)
    -> (Option<(BigUint,BigUint)>, u64)
{
    let ops = word_ops(word);
    let one = BigUint::one();
    if *n < BigUint::from(4u8) { return (None,0); }
    let lo = &one + &one;                 // 2
    let hi = n / (&one + &one);            // N/2, the whole legal band
    let mut a = isqrt_floor(n);
    if multiply_via_word(&a,&a) < *n { a = &a + &one; }
    let mut c = MathCarrier { n, lo:&lo, hi:&hi, a, delta:BigUint::zero(),
        b:BigUint::zero(), square:false, candidate:None, fixed:None, emitted:None };
    let mut ticks=0u64;
    for _ in 0..max_steps {
        for &op in &ops {
            let emitted = crate::gpu_kernel::nested_fixed_point_emit_pub(op, depth, &mut ticks);
            math_leaf(emitted, &mut c);
        }
        if let Some(pq) = c.emitted.take() { return (Some(pq), ticks); }
        if c.a > hi { break; }
    }
    (None, ticks)
}

/// The factorizer ob3ect family: name -> canonical glyph word, pulled from
/// ob3ect/digital. Each is run through the one math register above.
pub fn family()->Vec<(&'static str,&'static str)> {
    alloc::vec![
        ("aggregate_phase_morphism",      "⊢≻⋈⊙∈⊤≻⋈⊥≺⋈⊞∋⊡⋈⊙⊣"),
        ("closed_divisor_search",         "⊢⊣≻∈⊤⋈≺⊥⊞⊙∋⋈∈⊤≺⊥∋⊡⊣"),
        ("imscribing_factorizer",         "⊢⊣≻∈⊤⋈≺⊥⊞⊙⋈∈⊤≺⊥∋⊡⊣"),
        ("factor_separating_crossing",    "⊢∈≻⊤≺⊥⊞⋈∋⊙⊡⊣"),
        ("nested_instant_tower",          "⊢∈⊤≻⋈⊙⊡⊥≺⊞∋⋈⊙⊡⊣"),
        ("instant_nested_phase",          "⊢∈≻⊤≺⊥⋈⊙⊞⊡∋⊣"),
        ("fully_nested_phase",            "⊢∈≻⊤≺⊥⋈⊙⊞∋⊡⋈⊙⊣"),
        ("phase_based",                   "⊢⊙∈≻⊤⋈≺⊥⊞∋⊡⋈⊙⊣"),
        ("frobenius_circuit",             "⊢≻⊙∈⊤⋈⊥≺⊞∋⊡⊣"),
        ("trilattice_native",            "⊢≻⊙∈⊤⋈⊥≺⊞⊡∋⋈⊣"),
        ("carry_fuse_closure",            "⊢⊙∈≻⊤≺⊥⊞⋈∋⊡⊣"),
        ("prime_inverse_braider",         "⊢∈≻⊤≺⊥⊞⋈∋⊙⊡⊣"),
        ("full_enfolding_nesting",        "⊢⊣≻⋈⊙∈⊤⊥⊞≺⋈∋⊡⊙⊣"),
    ]
}

/// REPL/CLI face: `membrane <run WORD N | family N | list>`.
pub fn repl_membrane(args:&[&str])->String {
    let depth:u32 = 64;
    let max_steps:u64 = args.iter().position(|a|*a=="steps")
        .and_then(|i|args.get(i+1)).and_then(|s|s.parse().ok()).unwrap_or(200_000);
    match args.first().copied() {
        Some("list") => {
            let mut out=String::from("membrane family (name : word):\n");
            for (nm,w) in family() { out.push_str(&format!("  {nm:28} {w}\n")); }
            out
        }
        Some("run") if args.len()>=3 => {
            let word=args[1];
            let n = match args[2].parse::<BigUint>() { Ok(v)=>v, Err(_)=>return String::from("N must be decimal") };
            let (pq,ticks)=run_membrane(word,&n,depth,max_steps);
            match pq {
                Some((p,q))=>format!("membrane {word}\n  N={n}\n  {n} = {p} x {q} (verified={})\n  nested mark ticks={ticks}",
                    &multiply_via_word(&p,&q)==&n),
                None=>format!("membrane {word}\n  N={n}\n  no pair fixed in {max_steps} frontier steps (this word does not close N in the math register)\n  nested mark ticks={ticks}"),
            }
        }
        Some("family") if args.len()>=2 => {
            let n = match args[1].parse::<BigUint>() { Ok(v)=>v, Err(_)=>return String::from("N must be decimal") };
            let mut out=format!("math-register membrane family on N={n}\n");
            out.push_str(&format!("{:28} {:>10} {:>12} {}\n","MEMBRANE","TICKS","FACTORED","PAIR"));
            for (nm,w) in family() {
                let (pq,ticks)=run_membrane(w,&n,depth,max_steps);
                match pq {
                    Some((p,q))=>{
                        let ok = &multiply_via_word(&p,&q)==&n;
                        out.push_str(&format!("{nm:28} {ticks:>10} {:>12} {p} x {q}\n", if ok {"yes"} else {"BADVERIFY"}));
                    }
                    None=>out.push_str(&format!("{nm:28} {ticks:>10} {:>12} -\n","no")),
                }
            }
            out
        }
        _ => String::from("usage: membrane list | membrane run <WORD> <N> [steps K] | membrane family <N> [steps K]"),
    }
}

