/// Canonical interlace/deinterlace for native numerals.
///
/// There is exactly one numeral representation in this module: the word emitted
/// by `encode` / `encode_biguint`:
///
///   ⊢ (≻⋈∈bit∋)* ⊙⊡⊣
///
/// with cells ordered least-significant first and `⊤ = 0`, `⊥ = 1`.
/// Interlacing therefore acts on those cells directly.  It does not introduce a
/// second payload grammar or change bit order.
///
/// For lane words P and Q, Γ alternates their cells at each bit position:
///
///   Γ(P,Q)[2k]   = P[k]
///   Γ(P,Q)[2k+1] = Q[k]
///
/// Missing high cells are zero (`⊤`) while the other lane still has magnitude.
/// The result is canonicalized exactly as `encode` would canonicalize a value:
/// trailing high zero cells are omitted.  Λ is the inverse: even cells go to P,
/// odd cells go to Q, and each lane is canonicalized back to an `encode` word.

/// Parse only a canonical word produced by `encode`.
///
/// `decode` deliberately accepts the structural shape; the extra re-encode
/// equality here rejects non-canonical words with redundant high zero cells so
/// interlace/deinterlace really operate on *the output type of encode*.
fn canonical_encode_bits(word: &str) -> Result<Vec<bool>, &'static str> {
    let n = decode(word).ok_or("expected a native_numeral encode word")?;
    if encode_biguint(&n) != word {
        return Err("word is structurally decodable but is not canonical encode output");
    }
    Ok(to_bits_low_first(&n))
}

/// Build exactly the same word shape as `encode` from LSB-first bits.
/// High zero padding is discarded, just as `BigUint`/`encode` discard it.
fn encode_bits_canonical(bits: &[bool]) -> String {
    let mut end = bits.len();
    while end > 0 && !bits[end - 1] { end -= 1; }

    if end == 0 {
        return String::from("⊢⊙⊡⊣");
    }

    let mut w = String::new();
    w.push('⊢');
    for &bit in &bits[..end] {
        w.push('≻');
        w.push('⋈');
        w.push('∈');
        w.push(if bit { '⊥' } else { '⊤' });
        w.push('∋');
    }
    w.push('⊙');
    w.push('⊡');
    w.push('⊣');
    w
}

/// Γ on native-numeral words: interlace two canonical `encode` outputs and
/// return another canonical `encode` output.
pub fn interlace_words(p_word: &str, q_word: &str) -> Result<String, &'static str> {
    let p = canonical_encode_bits(p_word)?;
    let q = canonical_encode_bits(q_word)?;
    let width = p.len().max(q.len());

    let mut merged = Vec::with_capacity(width * 2);
    for k in 0..width {
        merged.push(p.get(k).copied().unwrap_or(false));
        merged.push(q.get(k).copied().unwrap_or(false));
    }
    Ok(encode_bits_canonical(&merged))
}

/// Λ on a native-numeral word: split one canonical `encode` output into its
/// even/odd cell lanes and return two canonical `encode` outputs.
pub fn deinterlace_word(word: &str) -> Result<(String, String), &'static str> {
    let bits = canonical_encode_bits(word)?;
    let mut p = Vec::with_capacity((bits.len() + 1) / 2);
    let mut q = Vec::with_capacity(bits.len() / 2);

    for (i, bit) in bits.into_iter().enumerate() {
        if i % 2 == 0 { p.push(bit); } else { q.push(bit); }
    }

    Ok((encode_bits_canonical(&p), encode_bits_canonical(&q)))
}

