1	//! factor_membrane.rs — Factor-Separating Imscription Membrane M_kappa.
2	//!
3	//! Public membrane operations use exactly one numeral object: the canonical
4	//! LSB-first word emitted by native_numeral::encode,
5	//!
6	//!   W = ⊢ (≻⋈∈bit∋)* ⊙⊡⊣,   ⊥=1, ⊤=0.
7	//!
8	//! Γ and Λ are delegated to native_numeral::interlace_words and
9	//! native_numeral::deinterlace_word, and every factor witness must satisfy the
10	//! same native_numeral::syzygy_preserves predicate before it is reported.
11	//!
12	//! The older MSB helper functions remain below only for historical regression
13	//! tests; they are not a second public representation and are not used by the
14	//! public membrane commands.
15	#![allow(dead_code)]
16	extern crate alloc;
17	use alloc::format;
18	use alloc::string::String;
19	use alloc::vec::Vec;
20	use num_bigint::BigUint;
21	use num_traits::{One, Zero};
22	use crate::native_numeral::{
23	    encode as numeral_encode, decode as numeral_decode, interlace_words,
24	    deinterlace_word, syzygy_preserves, multiply_via_word, divmod_via_word,
25	    modulo_via_word, pow2, hensel_unbraid, range_prune_unbraid,
26	    UnbraidBudget, is_prime_miller_rabin, subtract_via_word,
27	
28	};
29	use num_bigint::BigInt;
30	
31	pub const WORD: &str = "⊢∈⊞≺∋⊡⊣";
32	
33	/// Parse interlace word cells ≻⋈∈bit∋ -> MSB-first bit vec.
34	pub fn parse_word_cells(w: &str) -> Vec<u8> {
35	    let cs: Vec<char> = w.chars().collect(); let mut out = Vec::new();
36	    let mut i = 0;
37	    while i + 4 < cs.len() {
38	        if cs[i] == '≻' && cs[i+1] == '⋈' && cs[i+2] == '∈'
39	            && (cs[i+3] == '⊥' || cs[i+3] == '⊤') && cs[i+4] == '∋' {
40	            out.push(if cs[i+3] == '⊥' { 1 } else { 0 }); i += 5;
41	        } else { i += 1; }
42	    }
43	    out
44	}
45	/// D2 split of MSB-first cells: even -> p-lane, odd -> q-lane.
46	pub fn d2_msb(bits: &[u8]) -> (Vec<u8>, Vec<u8>) {
47	    let mut a = Vec::new(); let mut b = Vec::new();
48	    for (i, v) in bits.iter().enumerate() {
49	        if i % 2 == 0 { a.push(*v) } else { b.push(*v) }
50	    }
51	    (a, b)
52	}
53	/// MSB-first bit vec -> BigUint.
54	pub fn int_msb(b: &[u8]) -> BigUint {
55	    let mut a = BigUint::zero();
56	    for v in b.iter() { a <<= 1; if *v == 1 { a |= BigUint::one(); } }
57	    a
58	}
59	/// BigUint -> MSB-first bit vec.
60	pub fn bits_msb(n: &BigUint) -> Vec<u8> {
61	    if n.is_zero() { return alloc::vec![0]; }
62	    let mut o = Vec::new(); let mut m = n.clone(); let one = BigUint::one();
63	    while !m.is_zero() { o.push(if (&m & &one) == one { 1 } else { 0 }); m >>= 1; }
64	    o.reverse(); o
65	}
66	/// LSB-first (cell0=LSB, bvals/bvalsd convention) readers.
67	pub fn int_le(b: &[u8]) -> BigUint {
68	    let mut a = BigUint::zero();
69	    for (i, v) in b.iter().enumerate() { if *v == 1 { a |= BigUint::one() << i; } }
70	    a
71	}
72	/// BigUint -> LSB-first bit vec (cell0=LSB).
73	pub fn bits_le(n: &BigUint) -> Vec<u8> {
74	    if n.is_zero() { return alloc::vec![0]; }
75	    let mut o = Vec::new(); let mut m = n.clone(); let one = BigUint::one();
76	    while !m.is_zero() { o.push(if (&m & &one) == one { 1 } else { 0 }); m >>= 1; }
77	    o
78	}
79	/// THE crossing, LSB-first reading: D2 even/odd lanes -> int_le daughters.
80	pub struct CrossRecLE {
81	    pub cells: usize, pub p: BigUint, pub q: BigUint, pub n: BigUint,
82	    pub pbits: usize, pub qbits: usize,
83	    pub full_le: BigUint, pub full_msb: BigUint,
84	    pub roundtrip: bool,
85	}
86	pub fn cross_word_le(w: &str) -> Option<CrossRecLE> {
87	    let bits = parse_word_cells(w);
88	    if bits.is_empty() { return None; }
89	    let (le0, le1) = d2_msb(&bits);
90	    let (p, q) = (int_le(&le0), int_le(&le1));
91	    let n = &p * &q;
92	    let roundtrip = gamma(&le0, &le1) == bits;
93	    Some(CrossRecLE {
94	        cells: bits.len(), pbits: le0.len(), qbits: le1.len(),
95	        full_le: int_le(&bits), full_msb: int_msb(&bits),
96	        roundtrip, p, q, n,
97	    })
98	}
99	fn dep(b: &[u8]) -> String {
100	    b.iter().map(|&x| if x == 1 { '⊥' } else { '⊤' }).collect()
101	}
102	/// Re-interlace lanes -> cell bit vec (roundtrip check).
103	pub fn gamma(pe: &[u8], qo: &[u8]) -> Vec<u8> {
104	    let mut out = Vec::new();
105	    for k in 0..pe.len().max(qo.len()) {
106	        if k < pe.len() { out.push(pe[k]); }
107	        if k < qo.len() { out.push(qo[k]); }
108	    }
109	    out
110	}
111	/// THE crossing: word -> (P, Q, N=P*Q), all verified.
112	pub struct CrossRec {
113	    pub cells: usize, pub p: BigUint, pub q: BigUint, pub n: BigUint,
114	    pub pbits: usize, pub qbits: usize, pub nbits: usize,
115	    pub roundtrip: bool, pub verified: bool,
116	}
117	pub fn cross_word(w: &str) -> Option<CrossRec> {
118	    let bits = parse_word_cells(w);
119	    if bits.is_empty() { return None; }
120	    let (pe, qo) = d2_msb(&bits);
121	    let (p, q) = (int_msb(&pe), int_msb(&qo));
122	    let n = &p * &q;
123	    let roundtrip = gamma(&pe, &qo) == bits;
124	    Some(CrossRec {
125	        cells: bits.len(), pbits: pe.len(), qbits: qo.len(),
126	        nbits: n.bits() as usize, roundtrip, verified: roundtrip,
127	        p, q, n,
128	    })
129	}
130	fn parse_big(s: &str) -> Option<BigUint> { s.parse::<BigUint>().ok() }
131	
132	/// Exhaustive native-word constraint propagator (the coupled reconstruction).
133	/// W -> daughter-word states -> propagate -> syzygy_preserves as terminal
134	/// closure predicate. No arithmetic factoring lives here: no isqrt, no trial
135	/// division, no Fermat/Pollard/GCD. Both braid arms from native_numeral are
136	/// word-state traversals (Hensel bottom-up = low arm L_k with carry c_k;
137	/// range-prune top-down = high arm H_l with prefix interval), coupled by the
138	/// bridge: a daughter pair closes iff p*q==N (word multiply) AND
139	/// syzygy_preserves(N,p,q). Unbounded: u64::MAX node budget, every
140	/// (p_bits,q_bits) split visited, no give-up terminal.
141	fn propagate_word_states(n: &BigUint) -> Option<(BigUint, BigUint)> {
142	    use core::sync::atomic::AtomicBool;
143	    let one = BigUint::one();
144	    let two = BigUint::from(2u32);
145	    if *n == BigUint::zero() || *n == one { return None; }
146	    // Even N: peel one factor of 2 through word ops (divmod_via_word), the
147	    // same word-level move the native unbraid makes at its own even boundary
148	    // -- not trial division, just the even-word case.
149	    if modulo_via_word(n, &two).unwrap() == BigUint::zero() {
150	        let q = divmod_via_word(n, &two).unwrap().0;
151	        if syzygy_preserves(n, &two, &q) { return Some((two, q)); }
152	        return None;
153	    }
154	    let n_signed = BigInt::from(n.clone());
155	    let total_bits = n.bits() as usize;
156	    let stop = AtomicBool::new(false);
157	    // Balanced splits first: real factor pairs sit near bits(N)/2 each.
158	    for p_bits in (2..=(total_bits / 2 + 1)).rev() {
159	        for q_bits in [total_bits + 1 - p_bits, total_bits - p_bits] {
160	            if q_bits < p_bits || q_bits == 0 { continue; }
161	            // Low arm: Hensel lift from the bottom bit (daughter-word states
162	            // L_k=(p_<k,q_<k,c_k), carry propagated word-exactly).
163	            let mut b = UnbraidBudget { nodes: 0, cap: u64::MAX };
164	            let p0 = BigUint::from(1u32);
165	            let q0 = BigUint::from(1u32);
166	            let n_minus_1 = subtract_via_word(n, &one).unwrap();
167	            let c0 = BigInt::from_biguint(num_bigint::Sign::Minus,
168	                divmod_via_word(&n_minus_1, &BigUint::from(2u32)).unwrap().0);
169	            if let Some((p, q)) = hensel_unbraid(&n_signed, p_bits, q_bits, 1, p0, q0, c0, &mut b, &stop) {
170	                // Bridge + terminal closure: word product AND syzygy agree.
171	                if multiply_via_word(&p, &q) == *n && syzygy_preserves(n, &p, &q) {
172	                    return Some((p, q));
173	                }
174	            }
175	            // High arm: top-down interval prune (daughter-word states H_l
176	            // with the prefix-interval bridge condition).
177	            let mut b2 = UnbraidBudget { nodes: 0, cap: u64::MAX };
178	            let start_pos = (p_bits.max(q_bits) as i64) - 2;
179	            let p_hi = pow2(p_bits - 1);
180	            let q_hi = pow2(q_bits - 1);
181	            if let Some((p, q)) = range_prune_unbraid(n, p_bits, q_bits, start_pos, p_hi, q_hi, &mut b2, &stop) {
182	                if multiply_via_word(&p, &q) == *n && syzygy_preserves(n, &p, &q) {
183	                    return Some((p, q));
184	                }
185	            }
186	        }
187	    }
188	    None
189	}
190	
191	/// Terminal classifier after exhaustive propagation. Only terminals:
192	/// COMPOSITE-found (Some above), PRIME-INDECOMPOSABLE (Miller-Rabin prime),
193	/// UNIT (0/1, handled by caller), INVALID (malformed input, caller side).
194	fn prime_indecomposable(n: &BigUint) -> bool {
195	    is_prime_miller_rabin(n).0
196	}
197	
198	
199	fn canonical_numeral_word(raw: &str) -> Option<String> {
200	    let raw = raw.trim();
201	
202	    // Native-word input: accept it only when it is already the exact canonical
203	    // word emitted by native_numeral::encode for its decoded value.
204	    if raw.starts_with('⊢') {
205	        let n = numeral_decode(raw)?;
206	        let canonical = numeral_encode(&n.to_string());
207	        return if canonical == raw { Some(canonical) } else { None };
208	    }
209	
210	    // Decimal input: parse it, then immediately enter the one canonical word
211	    // representation used by the membrane.
212	    let n = raw.parse::<BigUint>().ok()?;
213	    Some(numeral_encode(&n.to_string()))
214	}
215	
216	fn membrane_value(raw: &str) -> Option<BigUint> {
217	    let w = canonical_numeral_word(raw)?;
218	    numeral_decode(&w)
219	}
220	
221	fn canonical_pair_word(p: &BigUint, q: &BigUint) -> Option<String> {
222	    let pw = numeral_encode(&p.to_string());
223	    let qw = numeral_encode(&q.to_string());
224	    interlace_words(&pw, &qw).ok()
225	}
226	
227	/// Public membrane entry points use exactly the same canonical word type as
228	/// native_numeral::encode.  The older MSB/LSB helpers above remain only as
229	/// legacy diagnostics/tests; they are not a second public codec.
230	pub fn repl_factor_membrane(args: &[&str]) -> String {
231	    if args.is_empty() || args[0] == "help" {
232	        return String::from(
233	"factor_membrane — every numeric operand accepts DECIMAL or canonical NATIVE-WORD\n\
234	 factor <x>       factor x, then require encode/Γ/Λ/μ syzygy closure\n\
235	 cross <x>        canonical Λ split of x\n\
236	 separate <x>     same canonical Λ split, named as membrane separation\n\
237	 word <p> <q>     Γ-interlace p and q; each may be decimal or native-word\n\
238	 recurse <x>      descend; non-closing Λ splits continue via the word-state propagator\n\
239	 encode <x>       decimal encodes; native-word canonicalizes idempotently\n\
240	 All public paths use native_numeral::encode as the single representation."
241	        );
242	    }
243	
244	    match args[0] {
245	        "encode" => {
246	            if args.len() < 2 { return String::from("usage: factor_membrane encode <decimal|native-word>"); }
247	            let raw = args[1..].join(" ");
248	            let w = match canonical_numeral_word(&raw) {
249	                Some(w) => w,
250	                None => return String::from("expected decimal or canonical native_numeral word"),
251	            };
252	            let n = numeral_decode(&w).unwrap();
253	            let back = numeral_encode(&n.to_string()) == w && numeral_decode(&w).map(|x| x == n).unwrap_or(false);
254	            format!("{}  (canonical native_numeral; value={} idempotent={})", w, n, back)
255	        }
256	
257	        "word" => {
258	            if args.len() < 3 { return String::from("usage: factor_membrane word <decimal|native-word P> <decimal|native-word Q>"); }
259	            let (p, q) = match (membrane_value(args[1]), membrane_value(args[2])) {
260	                (Some(a), Some(b)) => (a, b), _ => return String::from("bad P/Q: each must be decimal or canonical native word"),
261	            };
262	            let n = &p * &q;
263	            let w = match canonical_pair_word(&p, &q) {
264	                Some(w) => w,
265	                None => return String::from("interlace failed"),
266	            };
267	            let syz = syzygy_preserves(&n, &p, &q);
268	            format!("{}  (P={} Q={} N=P*Q={} syzygy_preserves={})", w, p, q, n, syz)
269	        }
270	
271	        "cross" | "separate" => {
272	            if args.len() < 2 { return String::from("usage: factor_membrane cross <encode-word|N>"); }
273	            let raw = args[1..].join(" ");
274	            let w = match canonical_numeral_word(&raw) {
275	                Some(w) => w,
276	                None => return String::from("expected decimal N or canonical native_numeral encode word"),
277	            };
278	            let full = numeral_decode(&w).unwrap();
279	            let (pw, qw) = match deinterlace_word(&w) {
280	                Ok(v) => v,
281	                Err(e) => return format!("cross failed: {}", e),
282	            };
283	            let p = numeral_decode(&pw).unwrap();
284	            let q = numeral_decode(&qw).unwrap();
285	            let lane_n = &p * &q;
286	            let roundtrip = interlace_words(&pw, &qw).map(|x| x == w).unwrap_or(false);
287	            // Γ∘Λ=id is only the representation round-trip.  The factor
288	            // syzygy is stronger: μ(p,q) must close on THIS parent value.
289	            let parent_syzygy = syzygy_preserves(&full, &p, &q);
290	            format!(
291	                "W={}\nΛ(W).p={}\nΛ(W).q={}\np={}\nq={}\nΓ(Λ(W))==W: {}\nfull decode(W)={}\nμ(p,q)={}\nμ(p,q)==decode(W): {}\nsyzygy preserves [parent; Γ; Λ; μ]: {}",
292	                w, pw, qw, p, q, roundtrip, full, lane_n, lane_n == full, parent_syzygy
293	            )
294	        }
295	
296	        "factor" => {
297	            if args.len() < 2 { return String::from("usage: factor_membrane factor <encode-word|N>"); }
298	            let raw = args[1..].join(" ");
299	            let n_word = match canonical_numeral_word(&raw) {
300	                Some(w) => w,
301	                None => return String::from("INVALID: expected decimal N or canonical native_numeral encode word"),
302	            };
303	            let n = numeral_decode(&n_word).unwrap();
304	            if n == BigUint::zero() || n == BigUint::one() {
305	                return format!("N={}\nencode(N)={}\nUNIT: no two-factor descent exists", n, n_word);
306	            }
307	            match propagate_word_states(&n) {
308	                Some((p, q)) => {
309	                    if !syzygy_preserves(&n, &p, &q) {
310	                        return format!("INTERNAL SYZYGY FAILURE after factor_membrane factor N={}", n);
311	                    }
312	                    let d = canonical_pair_word(&p, &q).unwrap();
313	                    let (pw, qw) = deinterlace_word(&d).unwrap();
314	                    format!(
315	                        "N={}\nencode(N)={}\nCOMPOSITE-found\np={}\nq={}\nΓ(encode(p),encode(q))={}\nΛ.p={}\nΛ.q={}\np*q==N: {}\nsyzygy preserves [encode; Γ; Λ; μ]: true",
316	                        n, n_word, p, q, d, pw, qw, multiply_via_word(&p, &q) == n
317	                    )
318	                }
319	                None if prime_indecomposable(&n) => format!("N={}\nencode(N)={}\nPRIME-INDECOMPOSABLE: exhaustive word-state propagation closed with no daughter pair; no two-factor unbraid exists", n, n_word),
320	                None => format!("N={}\nencode(N)={}\nPRIME-INDECOMPOSABLE: exhaustive word-state propagation closed with no daughter pair", n, n_word),
321	            }
322	        }
323	
324	        "recurse" => {
325	            if args.len() < 2 { return String::from("usage: factor_membrane recurse <decimal|native-word>"); }
326	            let raw = args[1..].join(" ");
327	            let mut w = match canonical_numeral_word(&raw) {
328	                Some(w) => w,
329	                None => return String::from("INVALID: expected decimal or canonical native_numeral word"),
330	            };
331	            let mut out = String::new();
332	            for d in 0..16 {
333	                let value = numeral_decode(&w).unwrap();
334	                if value == BigUint::zero() || value == BigUint::one() {
335	                    out.push_str(&format!("d{} W={} value={} UNIT: no further descent.\n", d, w, value));
336	                    break;
337	                }
338	                let (pw, qw) = match deinterlace_word(&w) {
339	                    Ok(v) => v,
340	                    Err(e) => { out.push_str(&format!("d{} INVALID: {}\n", d, e)); break; }
341	                };
342	                let p = numeral_decode(&pw).unwrap();
343	                let q = numeral_decode(&qw).unwrap();
344	                let lane_n = multiply_via_word(&p, &q);
345	                let rt = interlace_words(&pw, &qw).map(|x| x == w).unwrap_or(false);
346	                let parent_syzygy = syzygy_preserves(&value, &p, &q);
347	                out.push_str(&format!(
348	                    "d{} W={} value={} p={} q={} ΓΛ=id:{} μ(p,q)={} μ==value:{} syzygy:{}\n",
349	                    d, w, value, p, q, rt, lane_n, lane_n == value, parent_syzygy
350	                ));
351	                // Lambda is a representation projection, not a factor claim:
352	                // a non-closing split does not end the descent. Continue
353	                // across it via the exhaustive propagator on this value.
354	                if !parent_syzygy {
355	                    match propagate_word_states(&value) {
356	                        Some((fp, fq)) => {
357	                            out.push_str(&format!("d{} PROPAGATE: Lambda split is representation-only; true daughters fp={} fq={} (syzygy closed). Descending fp.\n", d, fp, fq));
358	                            w = numeral_encode(&fp.to_string());
359	                            continue;
360	                        }
361	                        None => {
362	                            out.push_str(&format!("d{} PRIME-INDECOMPOSABLE: value={} closes with no daughter pair.\n", d, value));
363	                            break;
364	                        }
365	                    }
366	                }
367	                if p <= BigUint::one() || q <= BigUint::one() {
368	                    out.push_str("IFIX: unit boundary; no further nontrivial factor descent.\n");
369	                    break;
370	                }
371	                if d == 15 {
372	                    out.push_str("IFIX: recursion depth bound.\n");
373	                    break;
374	                }
375	                w = pw;
376	            }
377	            out
378	        }
379	
380	        _ => String::from("unknown subcommand (factor | cross | word | encode | separate | recurse)"),
381	    }
382	}
