/// End-to-end syzygy invariant for the native numeral factor diagram.
///
/// This is deliberately stronger than checking either `p*q == N` or
/// `Λ(Γ(P,Q)) == (P,Q)` by itself.  All four stages must live in the same
/// canonical `encode()` representation and the whole diagram must commute:
///
///   W_N = encode(N)
///   W_p = encode(p), W_q = encode(q)
///   D   = Γ(W_p, W_q)
///   Λ(D) = (W_p, W_q)
///   encode( μ(Λ(D)) ) = W_N,  where μ is the native word multiplication.
///
/// `Γ(Λ(D)) == D` is checked as well, so both directions of the interlace
/// are required to preserve the same canonical word rather than merely its
/// decoded integer.
pub fn syzygy_preserves(n: &BigUint, p: &BigUint, q: &BigUint) -> bool {
    // μ must close on the parent before any representation claim is made.
    if multiply_via_word(p, q) != *n {
        return false;
    }

    let n_word = encode_biguint(n);
    let p_word = encode_biguint(p);
    let q_word = encode_biguint(q);

    // Every participant is required to be canonical encode output.
    if canonical_encode_bits(&n_word).is_err()
        || canonical_encode_bits(&p_word).is_err()
        || canonical_encode_bits(&q_word).is_err()
    {
        return false;
    }

    let d = match interlace_words(&p_word, &q_word) {
        Ok(w) => w,
        Err(_) => return false,
    };
    if canonical_encode_bits(&d).is_err() {
        return false;
    }

    let (p_back_word, q_back_word) = match deinterlace_word(&d) {
        Ok(v) => v,
        Err(_) => return false,
    };

    // Λ ∘ Γ = id on the two canonical arms.
    if p_back_word != p_word || q_back_word != q_word {
        return false;
    }

    // Γ ∘ Λ = id on the interlaced canonical word.
    if interlace_words(&p_back_word, &q_back_word).ok().as_deref() != Some(d.as_str()) {
        return false;
    }

    // μ after the split/fuse must return the exact canonical parent word,
    // not merely an equal-looking decimal produced through another codec.
    let p_back = match decode(&p_back_word) { Some(v) => v, None => return false };
    let q_back = match decode(&q_back_word) { Some(v) => v, None => return false };
    let recomposed = multiply_via_word(&p_back, &q_back);
    encode_biguint(&recomposed) == n_word
}

/// Human-readable witness of the same commuting diagram.
fn syzygy_line(n: &BigUint, p: &BigUint, q: &BigUint) -> String {
    format!(
        "syzygy preserves [encode; Γ; Λ; μ]: {}",
        syzygy_preserves(n, p, q)
    )

