            out.push_str(&format!("d{} W={} value={} UNIT: no further descent.\n", d, w, value));
            break;
        }
        let (pw, qw) = match deinterlace_word(&w) {
            Ok(v) => v,
            Err(e) => { out.push_str(&format!("d{} INVALID: {}\n", d, e)); break; }
        };
        let p = numeral_decode(&pw).unwrap();
        let q = numeral_decode(&qw).unwrap();
        let lane_n = multiply_via_word(&p, &q);
        let rt = interlace_words(&pw, &qw).map(|x| x == w).unwrap_or(false);
