    if !has(CONTINUE) { missing.push("CONTINUE (step the candidate)"); }
    if !has(FIX) { missing.push("FIX (latch)"); }
    if !missing.is_empty() {
        return Err(format!(
            "operator word does not carry factoring; missing: {}",
            missing.join(", ")
