/// Floor integer square root over numeral tapes, by binary search on the
/// largest x with x*x <= n. Used to seed and test the square-frontier arm.
fn isqrt(n: &[char]) -> Tape {
    if cmp(n, &two()) == core::cmp::Ordering::Less {
