    // p = 510511 (p-1 = 2·3·5·7·11·13·17, smooth), q = 92078429 far away.
    // Frontier is dead on the gap and rho crawls on the size, but the
    // nested p-1 arm closes it. Carrier: EXTRACT -> P_MINUS -> FIX.
    let p = 510511u64;
    let q = 92078429u64;
    let carrier = "⊢∈≻⊤≺⊥⊞⋈∋∈⊙⊞⋈∋⊙⊡⊣";
    let names: Vec<&str> = construct_carrier(carrier)
        .unwrap().iter().map(|t| morphism_name(t)).collect();
    assert_eq!(names, ["EXTRACT", "P_MINUS", "FIX"]);
    let f = factor_with(carrier, &numeral(p * q)).unwrap();
    assert!(f == numeral(p) || f == numeral(q));
}

