91	    // Entry ∈ and exit ∋ are the SAME frame; AREV ≺ sits INSIDE the frame so the
92	    // deposited marks bank and survive the reversal — the matched puncture.
93	    if c.len() >= 6
94	        && c.first() == Some(&VINIT)
95	        && c[1] == FSPLIT
96	        && c[c.len() - 1] == TANCH
97	        && c[c.len() - 2] == IFIX
98	        && c[c.len() - 3] == FFUSE
99	        && c[c.len() - 4] == AREV
100	    {
101	        let mut out = Vec::new();
102	        for &m in &c[2..c.len() - 4] {
103	            bit(m)?;
104	            out.push(m);
