116	    for cell in body.chunks(5) {
117	        if cell[0] != AFWD || cell[1] != CLINK || cell[2] != FSPLIT || cell[4] != FFUSE {
118	            return Err("broken native numeral cell".into());
119	        }
120	        bit(cell[3])?;
121	        out.push(cell[3]);
122	    }
123	    Ok(trim(out))
124	}
