fn l_divmod(n: &[u64], d: &[u64]) -> (Limbs, Limbs) {
    if l_is_zero(d) || l_cmp(n, d) == core::cmp::Ordering::Less {
        return (vec![0], l_trim(n.to_vec()));
    }
    let nb = l_bits(n);
    let mut q = vec![0u64; nb / 64 + 1];
    let mut r: Limbs = vec![0];
    for i in (0..nb).rev() {
        r = l_shl1(&r);
        if l_bit(n, i) {
            r[0] |= 1;
        }
        if l_cmp(&r, d) != core::cmp::Ordering::Less {
            r = l_sub(&r, d);
            q[i / 64] |= 1u64 << (i % 64);
        }
    }
    (l_trim(q), l_trim(r))
}

