1	//! Factoring over IMASM numeral tapes.
2	//!
3	//! A numeral is never decoded into a machine integer.  Its payload is a tape
4	//! of EVALT/EVALF marks, least significant cell first.  Arithmetic consumes
5	//! and produces those tapes through the full-adder/full-subtractor tables.
6	
7	use crate::vox::{AREV, AFWD, CLINK, EVALF, EVALT, FFUSE, FSPLIT, IFIX, IMSCRIB, TANCH, VINIT};
8	use alloc::format;
9	use alloc::string::String;
10	use alloc::vec;
11	use alloc::vec::Vec;
12	
13	type Tape = Vec<char>;
14	
15	const PHASE: &[char] = &[VINIT, FSPLIT, AFWD, EVALT, EVALF, FFUSE, TANCH];
16	const ARITHMETIC: &[char] = &[VINIT, FSPLIT, CLINK, EVALT, EVALF, FFUSE, TANCH];
17	const BRANCH: &[char] = &[VINIT, FSPLIT, EVALT, EVALF, FFUSE, TANCH];
18	const SELECT: &[char] = &[VINIT, FSPLIT, IMSCRIB, FFUSE, TANCH];
19	const CONTINUE: &[char] = &[VINIT, AFWD, CLINK, TANCH];
20	const FIX: &[char] = &[VINIT, IMSCRIB, IFIX, TANCH];
21	// The instant extract morphism: one evaluate frame carrying the involution
22	// (AREV ≺) and hold (ENGAGR ⊞) between the truth and falsity ports. It folds
23	// phase, arithmetic, select and continue into a single boundary, which is what
24	// makes the extractor a one-frame factorizer.
25	const EXTRACT: &[char] = &[VINIT, FSPLIT, AFWD, EVALT, AREV, EVALF, '⊞', CLINK, FFUSE, TANCH];
26	// Pollard p-1: seed an accumulator (IMSCRIB), raise it through rising exponents
27	// (ENGAGR), and take the gcd (CLINK) inside the frame. It catches a factor p
28	// whenever p-1 is smooth, at any size and any gap, covering the slice the
29	// frontier and rho arms miss.
30	const P_MINUS: &[char] = &[VINIT, FSPLIT, IMSCRIB, '⊞', CLINK, FFUSE, TANCH];
31	// Lenstra elliptic-curve method: seed a curve (IMSCRIB), advance a point under
32	// the group law (AFWD) and combine (CLINK) inside the frame. Each round tries
33	// one more curve; a factor falls out when the group law hits a non-invertible
