1	//! factor_operator.rs — the CL9NK moat resolver over IMASM numeral tapes.
2	//!
3	//! Ported from G-mOMonadOS `factor_operator.rs`. The primitive is not "search
4	//! for a factor" but "construct the factor pair as the fixed point of a
5	//! 2-adic winding". p and q are built one bit at a time from the low end; at
6	//! each level the only branches kept are those where p*q agrees with N on the
7	//! low k+1 bits (the exact winding constraint), pruned past sqrt(N) as the
8	//! magnitude bound, and a completion that closes on p*q = N is the fixation.
9	//! The count of branch nodes walked is the width of the moat, the free factor
10	//! bits held as paradox, read off the run rather than asserted.
11	//!
12	//! Arithmetic is the shared bit-register-folded numeral kernel in
13	//! morphism_factor, so the moat walk runs on folded tapes.
14	
15	use crate::morphism_factor::{cmp, isqrt, modulo, mul, parse_numeral, emit_numeral, trim};
16	use crate::vox::{EVALF, EVALT};
17	use alloc::format;
18	use alloc::string::String;
19	use alloc::vec;
20	use alloc::vec::Vec;
21	
22	type Tape = Vec<char>;
23	
24	fn one() -> Tape { vec![EVALF] }
25	fn two() -> Tape { vec![EVALT, EVALF] }
26	fn is_zero(t: &[char]) -> bool { trim(t.to_vec()) == [EVALT] }
27	fn gt_one(t: &[char]) -> bool { cmp(t, &one()) == core::cmp::Ordering::Greater }
28	
29	/// Return `base` with bit k set to v (LSB-first cells, padded with EVALT).
30	fn with_bit(base: &[char], k: usize, v: bool) -> Tape {
31	    let mut t = base.to_vec();
32	    while t.len() <= k {
33	        t.push(EVALT);
34	    }
35	    t[k] = if v { EVALF } else { EVALT };
36	    trim(t)
37	}
38	
39	/// Do prod and n agree on bits 0..=upto?
40	fn low_bits_match(prod: &[char], n: &[char], upto: usize) -> bool {
41	    for i in 0..=upto {
42	        let a = prod.get(i).copied().unwrap_or(EVALT);
43	        let b = n.get(i).copied().unwrap_or(EVALT);
44	        if a != b {
45	            return false;
46	        }
47	    }
48	    true
49	}
50	
51	/// Resolve the moat: fork each free bit into its two completions, keep only the
52	/// branch the winding constraint admits (p*q agrees with N on the low k+1
53	/// bits), bound by p,q <= sqrt(N), and lift until a completion closes on
54	/// p*q = N. Returns the factor pair, the branch-node count, and whether the
55	/// node budget capped the walk.
56	pub fn resolve_moat(n: &[char], max_nodes: u64) -> (Option<(Tape, Tape)>, u64, bool) {
57	    let root = isqrt(n);
58	    let bits = trim(n.to_vec()).len();
59	    let mut nodes: u64 = 0;
60	    let mut found: Option<(Tape, Tape)> = None;
61	    // DFS stack of (level k, p_low, q_low).
62	    let mut stack: Vec<(usize, Tape, Tape)> = vec![(0, vec![EVALT], vec![EVALT])];
63	    while let Some((k, plo, qlo)) = stack.pop() {
64	        if found.is_some() || nodes >= max_nodes {
65	            break;
66	        }
67	        if k >= bits + 1 {
68	            continue;
69	        }
70	        for pk in [false, true] {
71	            for qk in [false, true] {
72	                let p = with_bit(&plo, k, pk);
73	                let q = with_bit(&qlo, k, qk);
74	                nodes += 1;
75	                let prod = mul(&p, &q);
76	                if !low_bits_match(&prod, n, k) {
77	                    continue;
78	                }
79	                if cmp(&prod, n) == core::cmp::Ordering::Equal && gt_one(&p) && gt_one(&q) {
80	                    found = Some(if cmp(&p, &q) != core::cmp::Ordering::Greater {
81	                        (p.clone(), q.clone())
82	                    } else {
83	                        (q.clone(), p.clone())
84	                    });
85	                }
86	                // magnitude bound: the smaller factor cannot exceed sqrt(N).
87	                if cmp(&p, &root) == core::cmp::Ordering::Greater
88	                    && cmp(&q, &root) == core::cmp::Ordering::Greater
89	                {
90	                    continue;
91	                }
92	                stack.push((k + 1, p, q));
93	            }
94	        }
95	    }
96	    let capped = nodes >= max_nodes;
97	    (found, nodes, capped)
98	}
99	
100	/// Full factorization: strip the 2-part and small odd primes by the divisor
101	/// leg, then cross the moat for the balanced core. Returns the sorted factor
102	/// multiset, the total moat-node cost, and whether the budget held.
103	pub fn full_resolve(n0: &[char], small_bound: u64, max_nodes: u64) -> (Vec<Tape>, u64, bool) {
104	    let mut factors: Vec<Tape> = Vec::new();
105	    let mut moat_nodes: u64 = 0;
106	    let mut capped = false;
107	    let mut n = trim(n0.to_vec());
108	    // 2-part.
109	    while is_zero(&modulo(&n, &two())) {
110	        factors.push(two());
111	        n = crate::morphism_factor::divmod(&n, &two()).0;
112	    }
113	    // small odd primes to the cheap bound.
114	    let mut d = vec![EVALF, EVALF]; // 3
115	    let sb = crate::morphism_factor::tape_u64(small_bound);
116	    while cmp(&d, &sb) != core::cmp::Ordering::Greater
117	        && cmp(&mul(&d, &d), &n) != core::cmp::Ordering::Greater
118	    {
119	        while is_zero(&modulo(&n, &d)) {
120	            factors.push(d.clone());
121	            n = crate::morphism_factor::divmod(&n, &d).0;
122	        }
123	        d = crate::morphism_factor::add(&d, &two());
124	    }
125	    let sb2 = mul(&sb, &sb);
126	    let mut stack = vec![n];
127	    while let Some(c) = stack.pop() {
128	        if cmp(&c, &one()) != core::cmp::Ordering::Greater {
129	            continue;
130	        }
131	        if cmp(&c, &sb2) == core::cmp::Ordering::Less {
132	            factors.push(c);
133	            continue;
134	        }
135	        let (res, nodes, cap) = resolve_moat(&c, max_nodes);
136	        moat_nodes += nodes;
137	        if cap {
138	            capped = true;
139	            factors.push(c);
140	            continue;
141	        }
142	        match res {
143	            Some((p, q)) => {
144	                stack.push(p);
145	                stack.push(q);
146	            }
147	            None => factors.push(c),
148	        }
149	    }
150	    factors.sort_by(|a, b| cmp(a, b));
151	    (factors, moat_nodes, capped)
152	}
