154	fn to_dec(t: &[char]) -> String {
155	    // Small helper for the report: decode the tape to decimal via emit/parse
156	    // round-trip is not needed; render bits directly.
157	    let mut v = alloc::string::String::new();
158	    // Build decimal by repeated division by ten over tapes would be heavy; the
159	    // tape is already the answer, so print its decimal through a u128 when it
160	    // fits, else fall back to the numeral word.
161	    let bits = trim(t.to_vec());
162	    if bits.len() <= 127 {
163	        let mut acc: u128 = 0;
164	        for &c in bits.iter().rev() {
165	            acc = (acc << 1) | if c == EVALF { 1 } else { 0 };
166	        }
167	        v.push_str(&format!("{acc}"));
168	    } else {
169	        v.push_str(&emit_numeral(&bits));
170	    }
171	    v
172	}
