    // relation indices) to reach an all-even exponent sum.
    let rel = a_of.len();
    let hwords = rel / 64 + 1;
    let mut mat = rows.clone();
    let mut hist: Vec<Vec<u64>> = (0..rel)
        .map(|i| {
            let mut h = vec![0u64; hwords];
            h[i / 64] |= 1u64 << (i % 64);
            h
        })
        .collect();

